  const [tokens, setTokens] = useState([...mockTokens])
  const onTokenRemove = (tokenId: string | number) => {
    setTokens(
      tokens.filter((token: { id: string | number }) => token.id !== tokenId),
    )
  }
  return (
    <div className={classes.GridContainer}>
