import { Stack } from '@primer/react'
```

### Example

```tsx
() => (
  <Stack>
    <div
      style={{
        background: 'var(--display-lemon-bgColor-muted)',
        borderRadius: 'var(--borderRadius-medium)',
        padding: 'var(--base-size-8)',
      }}
