'use client'

import type {ReactNode} from 'react'
import {BaseStyles, ThemeProvider} from '@primer/react'

export function AppThemeProvider({children}: {children: ReactNode}) {
  return (
    <ThemeProvider colorMode="auto" dayScheme="light" nightScheme="dark">
      <BaseStyles>{children}</BaseStyles>
    </ThemeProvider>
  )
}

'use client'

import {useTheme} from '@primer/react'
import type {ColorModeWithAuto} from '@primer/react'

const COLOR_MODES: {value: ColorModeWithAuto; label: string}[] = [
  {value: 'auto', label: 'Auto (system)'},
  {value: 'day', label: 'Day'},
  {value: 'night', label: 'Night'},
]

const LIGHT_SCHEMES = [
  {value: 'light', label: 'Light'},
  {value: 'light-high-contrast', label: 'Light high contrast'},
  {value: 'light-colorblind', label: 'Light colorblind'},
