+'use client'
+
+import {useEffect, useState} from 'react'
+import {
+  COLOR_SCHEME_STORAGE_KEY,
+  COLOR_SCHEMES,
+  type ColorSchemeId,
+  DEFAULT_DARK_THEME,
+  DEFAULT_LIGHT_THEME,
+  getColorScheme,
+  SYSTEM_COLOR_SCHEME_ID,
+} from './color-schemes'
+
+function applyColorScheme(colorSchemeId: ColorSchemeId) {
+  const scheme = getColorScheme(colorSchemeId)
+  const root = document.documentElement
+
+  root.dataset.selectedColorScheme = scheme.id
+
+  if (scheme.mode === 'auto') {
+    root.dataset.colorMode = 'auto'
+    root.dataset.lightTheme = DEFAULT_LIGHT_THEME
+    root.dataset.darkTheme = DEFAULT_DARK_THEME
+    root.style.colorScheme = 'light dark'
+    return
+  }
+
+  root.dataset.colorMode = scheme.mode
+  root.dataset.lightTheme = scheme.mode === 'light' ? scheme.id : DEFAULT_LIGHT_THEME
+  root.dataset.darkTheme = scheme.mode === 'dark' ? scheme.id : DEFAULT_DARK_THEME
+  root.style.colorScheme = scheme.mode
+}
+
+function readStoredColorScheme(): ColorSchemeId {
+  return getColorScheme(window.localStorage.getItem(COLOR_SCHEME_STORAGE_KEY)).id
+}
+
+export function ColorSchemeSwitcher() {
+  const [selectedScheme, setSelectedScheme] = useState<ColorSchemeId>(SYSTEM_COLOR_SCHEME_ID)
+
+  useEffect(() => {
+    const storedScheme = readStoredColorScheme()
+    setSelectedScheme(storedScheme)
+    applyColorScheme(storedScheme)
+
+    function syncStoredScheme(event: StorageEvent) {
+      if (event.key !== COLOR_SCHEME_STORAGE_KEY) {
+        return
