+'use client'
+
+import type {CSSProperties} from 'react'
+import {useEffect, useMemo, useState} from 'react'
+import {
+  colorSchemes,
+  defaultColorSchemeId,
+  isColorSchemeId,
+  type ColorSchemeId,
+} from './color-schemes'
+
+const storageKey = 'preferred-color-scheme'
+
+type SchemeStyle = CSSProperties & {
+  [key: `--${string}`]: string
+}
+
+export function ColorSchemeSwitcher() {
+  const [selectedSchemeId, setSelectedSchemeId] = useState<ColorSchemeId>(defaultColorSchemeId)
+
+  useEffect(() => {
+    const storedSchemeId = window.localStorage.getItem(storageKey)
+
+    if (storedSchemeId && isColorSchemeId(storedSchemeId)) {
+      setSelectedSchemeId(storedSchemeId)
+    }
+  }, [])
+
+  const selectedScheme = useMemo(
+    () => colorSchemes.find((scheme) => scheme.id === selectedSchemeId) ?? colorSchemes[0],
+    [selectedSchemeId],
+  )
+
+  useEffect(() => {
+    window.localStorage.setItem(storageKey, selectedScheme.id)
+    document.documentElement.dataset.colorScheme = selectedScheme.id
+    document.documentElement.style.colorScheme = selectedScheme.colorScheme
+  }, [selectedScheme])
+
+  const schemeStyle: SchemeStyle = {
+    '--background': selectedScheme.colors.background,
+    '--foreground': selectedScheme.colors.foreground,
+    '--muted': selectedScheme.colors.muted,
+    '--surface': selectedScheme.colors.surface,
+    '--surface-alt': selectedScheme.colors.surfaceAlt,
+    '--accent': selectedScheme.colors.accent,
+    '--accent-foreground': selectedScheme.colors.accentForeground,
+    '--ring': selectedScheme.colors.ring,
+    colorScheme: selectedScheme.colorScheme,
+  }
+
+  return (
+    <main className="scheme-page" data-color-scheme={selectedScheme.id} style={schemeStyle}>
+      <section className="hero" aria-labelledby="page-title">
+        <p className="eyebrow">Color scheme support</p>
+        <h1 id="page-title">Switch between every available color scheme.</h1>
+        <p className="intro">
+          Pick any scheme below and the interface updates immediately. Your selection is saved for
+          the next visit.
+        </p>
+      </section>
+
+      <section className="scheme-panel" aria-labelledby="scheme-picker-title">
+        <div>
+          <h2 id="scheme-picker-title">Available schemes</h2>
+          <p className="current-scheme">
+            Current scheme: <strong>{selectedScheme.name}</strong>
+          </p>
+        </div>
+
+        <div className="scheme-grid" role="list">
+          {colorSchemes.map((scheme) => {
+            const isSelected = scheme.id === selectedScheme.id
+
+            return (
+              <button
+                aria-pressed={isSelected}
+                className="scheme-card"
+                data-selected={isSelected}
+                key={scheme.id}
+                onClick={() => setSelectedSchemeId(scheme.id)}
+                type="button"
+              >
+                <span className="scheme-card-header">
+                  <span>{scheme.name}</span>
+                  <span className="scheme-swatch" style={{background: scheme.colors.accent}} />
+                </span>
+                <span className="scheme-description">{scheme.description}</span>
+              </button>
+            )
+          })}
+        </div>
+      </section>
+    </main>
+  )
+}
