} from './constants'

type ThemeContextValue = {
  scheme: ColorScheme
  resolvedScheme: ResolvedColorScheme
  schemes: readonly ColorScheme[]
  setScheme: (scheme: ColorScheme) => void
}

const ThemeContext = createContext<ThemeContextValue | null>(null)

function readStoredScheme(): ColorScheme {
  if (typeof window === 'undefined') return DEFAULT_SCHEME
  try {
    const stored = window.localStorage.getItem(STORAGE_KEY)
    return isColorScheme(stored) ? stored : DEFAULT_SCHEME
  } catch {
    return DEFAULT_SCHEME
  }
}

function systemPrefersDark(): boolean {
  if (typeof window === 'undefined' || !window.matchMedia) return false
  return window.matchMedia('(prefers-color-scheme: dark)').matches
}

function resolve(scheme: ColorScheme): ResolvedColorScheme {
  if (scheme === 'system') return systemPrefersDark() ? 'dark' : 'light'
  return scheme
}

function applyScheme(scheme: ColorScheme, resolved: ResolvedColorScheme) {
  const root = document.documentElement
  root.dataset.theme = scheme
  root.dataset.resolvedTheme = resolved
  root.style.colorScheme = resolved
}

export function ThemeProvider({children}: {children: ReactNode}) {
  const [scheme, setSchemeState] = useState<ColorScheme>(DEFAULT_SCHEME)
  const [resolvedScheme, setResolvedScheme] =
    useState<ResolvedColorScheme>('light')

  useEffect(() => {
    const initial = readStoredScheme()
    const initialResolved = resolve(initial)
    setSchemeState(initial)
    setResolvedScheme(initialResolved)
    applyScheme(initial, initialResolved)
